EZTR_Basic_ReplaceText(0x064C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Volte sempre.|BF", NULL);
EZTR_Basic_ReplaceText(0x064D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Havera um show de fogos na noite|11antes do carnaval. Voce devia assistir.|11...Volte sempre.|BF", NULL);
