EZTR_Basic_ReplaceText(0x0757, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se voce encontrar todos os|01 cinco|00 ate|11|01amanha de manha|00, eu te ensino|11nosso codigo secreto. Pronto?|19", NULL);
EZTR_Basic_ReplaceText(0x0758, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Qual e o problema, cara?|11Voce se veste como se fosse todo|11descolado, mas nao e nada especial!|19", NULL);
EZTR_Basic_ReplaceText(0x0759, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que? Como assim?!|11Voce nao quer entrar para os|11|01Bombers|00?|19", NULL);
EZTR_Basic_ReplaceText(0x075A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce se lembra do codigo?|11E |01|00!|11|12Va pro |01esconderijo secreto|00 antes de|11esquecer! Fica em |01East Clock|11Town|00!|19", NULL);
