EZTR_Basic_ReplaceText(0x0772, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Pra voce, custa |0630 rupias|00.|11 |11|02|02|C2OK\n|11Nao, obrigado|BF", NULL);
EZTR_Basic_ReplaceText(0x0773, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ei... Pra voce, custa so |065 rupias|00.|11 |11|02|02|C2OK\n|11Nao, obrigado|BF", NULL);
EZTR_Basic_ReplaceText(0x0774, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, e mesmo? Que pena!|11...Volte sempre.|BF", NULL);
EZTR_Basic_ReplaceText(0x0775, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, e mesmo? Que pena!|11...Volte sempre.|BF", NULL);
EZTR_Basic_ReplaceText(0x0776, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah... e mesmo?|BF", NULL);
EZTR_Basic_ReplaceText(0x0777, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, e mesmo? Que pena! E voce|11ainda e bem do meu tipo...|BF", NULL);
EZTR_Basic_ReplaceText(0x0778, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se voce conseguir chegar ate o|11|01bau do tesouro|00 e |01abrir|00 ele|11dentro do |01limite de tempo|00, eu vou te dar|11um premio especial.|10Descobrir o que tem dentro e metade|11da diversao!|BF", NULL);
