EZTR_Basic_ReplaceText(0x07D4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce viu a entrada para a |01gaiola|00?|11|12Nos conhecemos uma |01rota secreta|00 ate la.|11|12Entre pela rota secreta pela entrada do |01Jardim|11Externo|00.|11|12Mas entrada esta em |01lugar alto|00. Nao podemos|11alcançar.|11|12Precisa de uma |01semente|00 do|01 vendedor de sementes|00. Mora|11|01embaixo|00 do jardim do palacio.|19", NULL);
EZTR_Basic_ReplaceText(0x07D5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mmm...|11Entendeu o que eu quis dizer?|11|02 |11|02|C2Nao\n|11Sim|BF", NULL);
EZTR_Basic_ReplaceText(0x07D6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mmm... entao...|19", NULL);
EZTR_Basic_ReplaceText(0x07D7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh! Voce e esperto.|11|12Plante a |01semente|00 no |01lugar macio|00 perto do|11|01Jardim Externo|00.|11|12O resto voce descobre. Rapido. Ajude|11o irmao.|19", NULL);
EZTR_Basic_ReplaceText(0x07D8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah! Voce veio! Voce veio!|19", NULL);
EZTR_Basic_ReplaceText(0x07D9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "E entao? E entao?|11Voce conseguiu?|11|12Acima esta a rota secreta que eu achei. Ela|11leva voce ate a |01gaiola|00.|19", NULL);
EZTR_Basic_ReplaceText(0x07DC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mmm...|11Siga-me!|BF", NULL);
EZTR_Basic_ReplaceText(0x07DD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mmm...|11Siga-me!|BF", NULL);
EZTR_Basic_ReplaceText(0x07DE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mmm...|11Siga-me!|BF", NULL);
EZTR_Basic_ReplaceText(0x0800, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, ", estou muito agradecido pelo que|11voce fez pela princesa.|11|12Como sinal de gratidao, nos Deku|11preparamos algo que achamos que pode te ajudar.|11Vou te levar ate la.|19", NULL);
EZTR_Basic_ReplaceText(0x0801, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A partir daqui, os caminhos sao escuros|11e podem ser bem perigosos...|11|12Por favor, me siga de perto e nao|11se separe de mim.|BF", NULL);
EZTR_Basic_ReplaceText(0x0802, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Muito bem, !|11|12Agora, aqui esta o item que prometi.|11Por favor, aceite.|19", NULL);
EZTR_Basic_ReplaceText(0x0803, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por favor, me siga.|BF", NULL);
EZTR_Basic_ReplaceText(0x0804, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Na verdade, quando vejo|11voce, lembro do meu |01filho|00 que saiu de casa|11ha muito tempo...|10De alguma forma, sinto como se estivesse|11correndo de novo com meu |01filho|00...|11|12Receio que posso ter me esforçado|11demais para correr de voce. Mesmo velho,|11ainda sou um bom corredor.|11Como quando eu corria com meu filho...|10Por favor, perdoe minha grosseria.|19", NULL);
EZTR_Basic_ReplaceText(0x0806, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah?!?|11Essa mascara...|11|12Parece com uma que meu filho costumava|11usar...|11|12Meu filho sempre usava essa mascara para|11achar |01cogumelos|00 na floresta. Ah,|11como tenho saudade desses dias.|11|12Fico pensando onde ele esta... o que|11ele esta fazendo...|11Se ao menos ele me enviasse uma|11carta...|10|17Desculpe-me.|18 Mais uma vez, pensamentos|11sobre meu filho me deixaram|11sentimental. Agora, onde estavamos?|19", NULL);
EZTR_Basic_ReplaceText(0x0807, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|BF", NULL);
EZTR_Basic_ReplaceText(0x080B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Sua Alteza!|11Estou implorando! Por favor, se|11acalme!|19", NULL);
EZTR_Basic_ReplaceText(0x080C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Agora que nossa amada princesa esta|11desaparecida, o rei nao consegue mais|11manter a calma...|19", NULL);
EZTR_Basic_ReplaceText(0x080D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Temo que a |01princesa|00 esteja envolvida|11em algum tipo de |01problema|00, assim como|11aquele macaco disse...|19", NULL);
EZTR_Basic_ReplaceText(0x080E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas nesse estado, o rei nao pode nem|11enviar tropas para procura-la.|11O que vamos fazer?|19", NULL);
EZTR_Basic_ReplaceText(0x080F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "E muito triste...|11Mas nada pode acalmar o rei|11agora...|11|12Nossos pantanos estao|11envenenados... Isso pode ser o fim|11do Reino Deku!|19", NULL);
EZTR_Basic_ReplaceText(0x0810, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, grandes senhores! Salvem-nos!|19", NULL);
EZTR_Basic_ReplaceText(0x0811, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, grandes senhores! Por favor, salvem-nos!|19", NULL);
EZTR_Basic_ReplaceText(0x0820, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Estavamos prestes a punir um|11macaco inocente!|BF", NULL);
EZTR_Basic_ReplaceText(0x0821, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mais do que tudo, estou apenas feliz|11que a princesa voltou em seguranca.|BF", NULL);

