EZTR_Basic_ReplaceText(0x0828, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Parece que voce gosta de ver ele!|19", NULL);
EZTR_Basic_ReplaceText(0x0829, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Siga este corredor |01reto|00 ate a|11|01Camara Real|00. Nao entre em|11nenhuma outra area!|19", NULL);
EZTR_Basic_ReplaceText(0x082A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu disse para nao entrar em nenhuma|11area que nao seja a |01Camara Real|00!|19", NULL);
