EZTR_Basic_ReplaceText(0x085E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Otimo. Crianças pagam |0610 rupias|00!|19", NULL);
EZTR_Basic_ReplaceText(0x085F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Bem, venha me ver se mudar de ideia...|BF", NULL);
