EZTR_Basic_ReplaceText(0x086C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nao parece divertido?|11Entao, quer tentar?|11|02|02|C2Claro\n|11Nao, obrigado|BF", NULL);
EZTR_Basic_ReplaceText(0x086D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por que nao?!? Nao gosta de brincar|11com gente velha?|11|12Ah, entendi! Nesse caso, fora! Fora!|11Pode ir embora!|BF", NULL);
