EZTR_Basic_ReplaceText(0x0880, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|01Poçao Azul: 60 rupias|11|00Na verdade, nao consigo os|11ingredientes pra isso, entao|11esta esgotado. Desculpe.|BF", NULL);
EZTR_Basic_ReplaceText(0x0881, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que e isso? Quer uma |03Poçao|11Azul|00, e isso?|11|12Bem, voce me deu um cogumelo, entao|11vou te dar uma de graça.|19", NULL);
EZTR_Basic_ReplaceText(0x0882, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Snif, snif... Acho que estou sentindo|11o leve perfume de cogumelos...|11Voce tem algum?|19", NULL);
EZTR_Basic_ReplaceText(0x0883, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mmmm... Que aroma!|11Voce fez um otimo trabalho|11achando esse aqui!|11|12Eu nao conseguia encontrar nenhum|11e isso me deixou em apuros!|19", NULL);
