EZTR_Basic_ReplaceText(0x088C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas da proxima vez voce vai ter que pagar.|11Ah... e nao conte pra Koume!|19", NULL);
EZTR_Basic_ReplaceText(0x088D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se tirar uma boa foto do barco, leve|11para aquele sujeito ali.|11|12Certo... O barco esta saindo!|BF", NULL);
EZTR_Basic_ReplaceText(0x088E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|17Ora, sua garrafa ja esta cheia!|18|11|12Nao posso te vender |01poçoes|00 a|11menos que tenha uma |01garrafa vazia|00!|19", NULL);
EZTR_Basic_ReplaceText(0x088F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que ta fazendo parado ai?|11Odeio preguiçosos!|19", NULL);
EZTR_Basic_ReplaceText(0x0890, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh! Que mascara bonita voce esta|11usando!|11|12Com essa mascara, voce pode encontrar|11os |01cogumelos|00 que crescem na|11|01floresta|00.|11|12Ache varios e traga aqui!|19", NULL);
EZTR_Basic_ReplaceText(0x0898, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Todo mundo!|11Corram e preparem o caldeirao|11agora mesmo!!!|BF", NULL);
