EZTR_Basic_ReplaceText(0x089A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Normalmente, nao deixo alguem como|11voce entrar na minha Camara Real, mas|11hoje e diferente!|11|12Estamos prestes a punir o tolo|11|01macaco|00 que |01sequestrou|00 a |01princesa|11Deku|00!|19", NULL);

EZTR_Basic_ReplaceText(0x089B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ele insultou a Familia Real.|11Vou mostrar o que acontece quando|11se faz isso!|19", NULL);
EZTR_Basic_ReplaceText(0x089C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Aquele |01macaco tolo|00 esta naquela|11|01gaiola|00. De uma boa olhada na|11cara dele!|BF", NULL);
EZTR_Basic_ReplaceText(0x089D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "E entao?|11...Quente, nao?|11|12O macaco vai sofrer e|11sofrer ate nao aguentar mais!|19", NULL);
EZTR_Basic_ReplaceText(0x089E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce vai conhecer a furia de um|11rei cuja princesa adorada foi|11levada!!!|BF", NULL);
EZTR_Basic_ReplaceText(0x089F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Sofra!|11Vou prolongar o sofrimento dele!|11Tolo |01macaco|00!|BF", NULL);
EZTR_Basic_ReplaceText(0x08A0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, minha princesa! Minha querida|11princesa!!! Voce esta bem?|11Eu estava tao preocupado.|BF", NULL);
EZTR_Basic_ReplaceText(0x08A1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Tomar decisoes precipitadas e meu|11ponto fraco... Desta vez, mais do que|11nunca, percebi isso.|19", NULL);
EZTR_Basic_ReplaceText(0x08A2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, estranho viajante, ha|11pouco que posso fazer. Descanse|11um pouco antes de partir.|BF", NULL);
EZTR_Basic_ReplaceText(0x08A3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Todos, ouviram isso?|BF", NULL);
EZTR_Basic_ReplaceText(0x08A4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Essa melodia, que so a Familia Real|11Deku conhece...|11|12Prova que o macaco tolo|11enganou a princesa para entrar no|11templo!|BF", NULL);
EZTR_Basic_ReplaceText(0x08A5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Todos!|11Que comecem os castigos do macaco!|BF", NULL);
EZTR_Basic_ReplaceText(0x08CA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eles continuam dizendo que eu|11sequestrei ela. Nao importa quantas|11vezes digam, isso nao vai trazer a|11|01princesa|00 de volta! |10Se nao tiverem cuidado, a |01princesa|11|00sera vitima de um monstro!|19", NULL);
