EZTR_Basic_ReplaceText(0x0E4D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Este e o quarto do Anciao da Tribo Goron.|11|12Voce tem algum assunto com o Anciao?|11Infelizmente, ele saiu.|19", NULL);
EZTR_Basic_ReplaceText(0x0E4E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Desde que o Anciao saiu, seu filho nao para de chorar. Queria que alguem fizesse algo...|BF", NULL);
EZTR_Basic_ReplaceText(0x0E4F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Essas suicoes... Voce nao e Darmani? Você estava morto... mas esta vivo?|11O que voce tem feito?|19", NULL);
EZTR_Basic_ReplaceText(0x0E50, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Pensando que voce estava morto, o Anciao foi para |01Snowhead|00 sozinho...|11|12Mas por agora, va ver o filho do Anciao. Rapido!|BF", NULL);
EZTR_Basic_ReplaceText(0x0E51, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O filho do Anciao esta ali.|11...Este choro e de partir o coracao.|11Sera que vai parar?|BF", NULL);
EZTR_Basic_ReplaceText(0x0E52, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Esta loja esta com problemas para receber produtos por causa do frio. As coisas estao caras, melhor nao comprar aqui.|BF", NULL);
EZTR_Basic_ReplaceText(0x0E74, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Waaa... Hunh, ugh...u-waahhh!|11P-papai, papai! Hunh...|11Estou com frio... Papai!|BF", NULL);
EZTR_Basic_ReplaceText(0x0E75, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Hyunh, hunh...|11Ah, Darmi, cadê meu papai?|11Cadê meu papai?|19", NULL);
EZTR_Basic_ReplaceText(0x0E76, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Waaah... Henh, uwaaaaah...|11Paaaapai, papai... H-hunh...|11Estou com frio, Papai!|19", NULL);
EZTR_Basic_ReplaceText(0x0E77, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Essa musica... E a que o papai sempre toca para eu dormir...|11Vou cantar o proximo verso.|BF", NULL);
EZTR_Basic_ReplaceText(0x0E78, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mmmmm...|11E como se... o papai...|11estivesse aqui...|BF", NULL);
EZTR_Basic_ReplaceText(0x0E79, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Zzzzz...|BF", NULL);
EZTR_Basic_ReplaceText(0x0E7A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, Darmi!|BF", NULL);
EZTR_Basic_ReplaceText(0x0E7B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Agora que esta quente, estou muito melhor.|11|12Mesmo sem meu papai aqui, nao vou ser egoista e chorar.|BF", NULL);
EZTR_Basic_ReplaceText(0x0E7C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Entao... com a chegada da primavera, as Corridas Goron devem comecar em breve.|BF", NULL);
