EZTR_Basic_ReplaceText(0x0E87, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Depois de ver as Corridas Goron, voce vai querer ter nascido Goron.|BF", NULL);
EZTR_Basic_ReplaceText(0x0E88, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah! Darmi!|11Estava te esperando.|11|12Todo mundo esta ansioso para entrar. Voce vai entrar, nao vai?|BF", NULL);
EZTR_Basic_ReplaceText(0x0E89, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce vai entrar, nao vai?|11 |11|02|02|C2Sim\n|11Nao|BF", NULL);
EZTR_Basic_ReplaceText(0x0E8A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Voce gostava mais de correr do que de devorar um terceiro prato de pedra...|BF", NULL);
EZTR_Basic_ReplaceText(0x0E8B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O Darmi que conheco nunca recuaria de uma corrida...|BF", NULL);
EZTR_Basic_ReplaceText(0x0E8C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu odeio!|11Quero ver voce correr!|11|17Eu quero!|18 |17Eu quero!|18 |17Eu quero!|18", NULL);

