EZTR_Basic_ReplaceText(0x0FAB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Pensando bem, e engraçado te ver|11por aqui.|19", NULL);  
EZTR_Basic_ReplaceText(0x0FAC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que e isso? Nao sabe fechar a|11boca quando ouve alguem?|19", NULL);  
EZTR_Basic_ReplaceText(0x0FAD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O mar aqui tá quente demais pra|11você nadar. Se nao tem negocio,|11vaza.|19", NULL);  
EZTR_Basic_ReplaceText(0x0FAE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O mar tá quente pra você.|11Se nao tem nada pra fazer, cai fora.|19", NULL);  
EZTR_Basic_ReplaceText(0x0FAF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ta entendendo algo com essa boca|11aberta?|19", NULL);  
EZTR_Basic_ReplaceText(0x0FB0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Cadê os outros ovos? So eclodem|11se |01todos|00 estiverem juntos.|11|12Rapido! Encontre os ovos e coloque|11no aquario.|19", NULL);  
EZTR_Basic_ReplaceText(0x0FB1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Finalmente chegou? E os ovos?|11|12Sao |01sete|00 no total...|11Rapido! Coloque no |01aquario|00.|19", NULL);  
