EZTR_Basic_ReplaceText(0x1F4E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05|17Otimo! Entao esta|11combinado!|18|11|12Agora, serei sua parceira...|11pelo menos ate pegarmos aquele|11Skull Kid...|11|12Meu nome é |01Tatl|05.|11Entao, uh, prazer em te conhecer|11ou algo assim.|BF", NULL);
EZTR_Basic_ReplaceText(0x1F4F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Agora que tudo esta resolvido,|11podemos parar de enrolar e seguir?|11|12Se eu descobrir algo,|11aperte [C-Cima] que eu te conto.|11Espero que voce consiga se virar|11sem minha ajuda ate la!|BF", NULL);
EZTR_Basic_ReplaceText(0x1F50, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Aww, buáá.|11Por que essa carinha triste?|11|12So pensei em me divertir um pouco|11com voce...|BF", NULL);
EZTR_Basic_ReplaceText(0x1F51, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ora, vamos...|11Voce realmente acha que pode me vencer|11do jeito que estou agora?|11Tolo!|BF", NULL);
