EZTR_Basic_ReplaceText(0x28D5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Não consigo encontrá-lo...|11Kafei...|11|12Onde...|11Onde será que ele foi parar...|11|12E falta tão pouco tempo|11antes...|11do nosso casamento...|BF", NULL);
EZTR_Basic_ReplaceText(0x28D6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah! ...Uhm...Deixa pra lá!|BF", NULL);
EZTR_Basic_ReplaceText(0x28D7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Sinto muito incomodá-lo tarde da|11noite. É sobre ele...Kafei.|19", NULL);
EZTR_Basic_ReplaceText(0x28D8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Recebi uma carta dele...|11|12Estranho...Não é?|11Receber uma carta de uma pessoa|11desaparecida...|11|12Mas não há absolutamente nenhum engano|11de que é dele!|11|12Está claro...para mim...|19", NULL);
EZTR_Basic_ReplaceText(0x28D9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por favor!|19", NULL);
EZTR_Basic_ReplaceText(0x28DA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Aqui está minha carta.|11Por favor, coloque-a em uma caixa de correio.|11|12Quando isso for entregue...Quando ele|11receber minha carta... Você poderá|11encontrá-lo!|11|12Por favor, diga a ele que Anju está|11esperando por ele.|11|12E, por favor, depois de tê-lo|11visto...|11Diga-me como ele parecia.|11|12Estou com medo...Eu...Eu não posso ir.|19", NULL);
EZTR_Basic_ReplaceText(0x28DB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Posso te pedir isso?|11 |11|02|02|C2Sim\n|11Não|BF", NULL);
EZTR_Basic_ReplaceText(0x28DC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Muito obrigado...mesmo.|BF", NULL);
EZTR_Basic_ReplaceText(0x28DE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por favor, envie imediatamente pela|11manhã.|19", NULL);
EZTR_Basic_ReplaceText(0x28DF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Uh, hummm...Você não vai|11se refugiar?|BF", NULL);
EZTR_Basic_ReplaceText(0x28E0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Ah...O tempo de hoje é|11desfavorável, não é?|BF", NULL);
EZTR_Basic_ReplaceText(0x28E1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu decidi esperar por ele.|11Fiz minha promessa...|11|12Estou bem com isso.|11Eu acredito nele.|BF", NULL);
EZTR_Basic_ReplaceText(0x28E2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh...|11|12Você...o viu?|11|12...Me desculpe. É tarde demais, não é?|BF", NULL);
EZTR_Basic_ReplaceText(0x28E3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh...|11|12Você...o viu?|11|12...Me desculpe.|11Provavelmente é muito cedo para perguntar...|BF", NULL);
EZTR_Basic_ReplaceText(0x28E4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh...|11|12Você o encontrou?|19", NULL);
EZTR_Basic_ReplaceText(0x28E5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah!|19", NULL);
EZTR_Basic_ReplaceText(0x28E6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...É do Kafei.|11M-mu-muito obrigado...|11Muito mesmo!|BF", NULL);
EZTR_Basic_ReplaceText(0x28E7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Uhm...O que é isso?|BF", NULL);
EZTR_Basic_ReplaceText(0x28E8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Com licença.|11Você viu um homem nesta|11área?|19", NULL);
EZTR_Basic_ReplaceText(0x28E9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ele se parece com isto...|19", NULL);
EZTR_Basic_ReplaceText(0x28EA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ele...desapareceu há cerca de um mês|11com sua |01máscara de cerimônia de|11casamento|00.|19", NULL);
EZTR_Basic_ReplaceText(0x28EB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu...na verdade...tenho medo de encontrá-lo...|11|12e de ouvir o motivo pelo qual ele|11quis desaparecer...|11|12Pode ser por causa de... mim...|19", NULL);
EZTR_Basic_ReplaceText(0x28EC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Faltam apenas |01dois dias |00para o|11carnaval...|11Devo esperar?|11Kafei...|19", NULL);
EZTR_Basic_ReplaceText(0x28ED, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah! Aquela máscara...|11Você também está procurando por ele.|19", NULL);
EZTR_Basic_ReplaceText(0x28EE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Vim para cá pensando em procurá-lo|11eu mesma, mas...|19", NULL);
EZTR_Basic_ReplaceText(0x28EF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Que pousada caindo aos pedaços. Este|11quarto é de primeira classe? Dá para ouvir|11quem está ao lado gritando!|10Bem, tanto faz... Estamos hospedados de|11graça, então não podemos esperar muito.|BF", NULL);
EZTR_Basic_ReplaceText(0x28F0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Veja, tudo aqui está caindo|11aos pedaços... Você pode ouvir as vozes|11do lado.|BF", NULL);
EZTR_Basic_ReplaceText(0x28F1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "OK, Anju, vamos sair à|11noite para o rancho.|11|12|01Cremia|00 vai nos acolher. Ela é|11sua melhor amiga, certo?|19", NULL);
EZTR_Basic_ReplaceText(0x28F2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Será que Kafei realmente está no|11lugar da |01Cremia|00...?|19", NULL);
EZTR_Basic_ReplaceText(0x28F3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se Kafei estiver lá, sua mãe vai|11dar um tapa nele.|11|12Além disso, pense na Cremia. Ela|11precisa da força de um parceiro e|11apoio nos negócios da Madame|11Aroma.|10Se Kafei realmente fugiu com|11Cremia, ela terá os dois. Por favor,|11não fique triste. Quão feliz você|11poderia ser...|10casando-se com um homem que foge|11quando está prestes a se casar?|11Isso tornaria sua vida infeliz|11...assim como a de sua mãe.|19", NULL);
EZTR_Basic_ReplaceText(0x28F4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas na carta dizia que ele|11definitivamente voltaria...|19", NULL);
EZTR_Basic_ReplaceText(0x28F5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voltar para quê??|11Esta cidade não será esmagada|11sob a manhã de depois de|11amanhã?|10Esqueça essa carta. Por enquanto,|11apenas tente sobreviver.|11Todo o resto virá...|19", NULL);
EZTR_Basic_ReplaceText(0x28F6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Sim...|11Mãe, obrigado.|19", NULL);
EZTR_Basic_ReplaceText(0x28F7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Todos estarão se refugiando|11logo pela manhã. Tudo deveria estar tão|11...animado...É triste.|19", NULL);
EZTR_Basic_ReplaceText(0x28F8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Estaremos indo para o Rancho Romani à|11noite para nos refugiarmos. Acho que|11vocês também deveriam se apressar.|BF", NULL);
EZTR_Basic_ReplaceText(0x28F9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Talvez eu estivesse errada...|19", NULL);
EZTR_Basic_ReplaceText(0x28FA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas ele disse...|11Na manhã da cerimônia...|11Ele viria me encontrar no meu quarto...|19", NULL);
EZTR_Basic_ReplaceText(0x28FB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "E eu prometi a ele que esperaria...|11Mas...já...é tarde demais, não é?|BF", NULL);
EZTR_Basic_ReplaceText(0x28FC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Anju ficou em seu quarto esperando|11por Kafei...|11|12É tolice acreditar em um homem|11assim.|11|12Eu também acreditei que meu marido|11voltaria do nada...|11|12Oh, Anju...|11Aquele senso ingênuo de confiança da criança|11pode ser minha culpa.|BF", NULL);
EZTR_Basic_ReplaceText(0x28FD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "!!!|19", NULL);
EZTR_Basic_ReplaceText(0x28FE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Eu fui um pouco dura com a Anju.|11...Mas, está tudo bem assim.|11|12Agora, sobreviver é o|11importante.|BF", NULL);
EZTR_Basic_ReplaceText(0x28FF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Sinto muito.|11Nós vamos nos refugiar à|11noite como os outros.|11|12Você também deveria correr.|11Parece que vai cair|11amanhã de manhã.|BF", NULL);
EZTR_Basic_ReplaceText(0x2900, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Sinto muito.|11Nossos quartos estão ocupados.|BF", NULL);
EZTR_Basic_ReplaceText(0x2901, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, Tortus, você está atrasado...|11|12Amanhã é mais um dia cedo, então|11boa noite. Vou ler uma história para você|11amanhã.|BF", NULL);
EZTR_Basic_ReplaceText(0x2902, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, Tortus.|11Você terminou de ajudar o papai?|11|12Então deixe a mamãe te ler uma história.|19", NULL);
EZTR_Basic_ReplaceText(0x2903, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Agora, qual história você gostaria|11de ouvir?|11|12|02Vou passar|11Carnaval do Tempo |01 (2 horas)|11|02Quatro Gigantes |01(Até de manhã)|BF", NULL);
EZTR_Basic_ReplaceText(0x2904, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O Carnaval do Tempo, é isso?|11|12O carnaval está quase aí, então é|11bom para você aprender o seu significado.|11É um pouco longo, mas vou lê-lo|11com um pouco de entusiasmo. Ahem...|10|11Cada ano, a estação da harmonia|11começa quando o sol e a lua|11estão em alinhamento.|10Prestando homenagem à forma como|11a natureza e o tempo estão|11incansavelmente em processo de|11progresso...|10o Carnaval do Tempo é quando os|11povos dos quatro mundos|11celebram essa harmonia e|11pedem prosperidade para o ano.|19", NULL);
EZTR_Basic_ReplaceText(0x2905, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por séculos, as pessoas usaram máscaras|11semelhantes aos gigantes que são os|11deuses dos quatro mundos.|11|12Agora, tornou-se um costume para|11cada pessoa trazer uma máscara feita à mão|11para o Carnaval do Tempo.|11|12Diz-se que se um casal se unisse|11no dia do festival e|11dedicasse uma máscara como sinal de|11sua união, traria sorte.|10O ponto central do carnaval é|11a torre do relógio, e na véspera|11de todas as festividades, as portas de|11seu telhado são abertas...|10Do topo do telhado da torre do relógio, uma|11cerimônia para chamar os deuses é realizada|11e uma canção antiga é cantada.|11|12Todas essas festividades para o|11Carnaval do Tempo são realizadas para que|11possamos pedir aos deuses uma rica|11colheita no ano que virá!|19", NULL);
EZTR_Basic_ReplaceText(0x2906, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Você fez um bom trabalho!|11Isso é tudo para o Tortus!|11|12Agora, quando o telhado da torre|11do relógio abre?|11|02|02|C2na véspera do festival\n|11Eu não sei|BF", NULL);
EZTR_Basic_ReplaceText(0x2907, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Bem, nesse caso, tente de novo|11com a mamãe.|BF", NULL);
EZTR_Basic_ReplaceText(0x2908, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Você se lembrou bem.|11Esse é o garoto de quem me orgulho.|19", NULL);
EZTR_Basic_ReplaceText(0x2909, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Vou te dar um doce como|11prêmio.|19", NULL);
EZTR_Basic_ReplaceText(0x290A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, você está acordado?|11|12Acho que aquela história foi um pouco|11chata para o Tortus, não foi?|11|12Não desista. Tente de novo algum dia.|BF", NULL);
EZTR_Basic_ReplaceText(0x290B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|01Os Quatro Gigantes|00, é isso?|11|12Esta é bem longa, mas é uma boa|11história para você ouvir, então vou lê-la|11com um pouco mais de entusiasmo.|11Ahem...|10|11Esta história é de muito tempo atrás, quando todas|11as pessoas não estavam separadas em|11quatro mundos como estão agora.|10Naqueles tempos, todas as pessoas viviam|11juntas, e os quatro gigantes viviam|11entre elas.|11|12No dia do festival que|11celebra a colheita, os gigantes|11falaram com as pessoas...|11|12|11|BF", NULL);
EZTR_Basic_ReplaceText(0x290C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Agora então...Houve um que|11ficou chocado e entristecido com|11tudo isso.|11|12Um pequeno duende.|11|12O duende era amigo dos|11gigantes desde antes de terem|11criado os quatro mundos.|11|12|11 |11|11|12O amigo de infância sentiu-se|11negligenciado, então espalhou sua raiva|11pelos quatro mundos.|11Repetidamente, ele prejudicou todas as pessoas.|10Oprimidas pela desgraça, as|11pessoas cantaram a canção de oração para|11os gigantes que viviam em cada uma|11das quatro direções cardeais.|10Os gigantes ouviram seu clamor e|11responderam com um rugido.|11|10|11|10O duende ficou assustado e|11entristecido.|11 |11Ele havia perdido seus velhos amigos.|10O duende retornou aos céus,|11e a harmonia foi restaurada aos|11quatro mundos.|11|12E as pessoas se alegraram e|11adoraram os gigantes dos quatro|11mundos como deuses. E viveram|11felizes...para sempre...|19", NULL);
EZTR_Basic_ReplaceText(0x290D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Bom trabalho! Não foi divertido,|11Tortus?|11|12O que as pessoas fizeram para chamar os|11gigantes?|11|02|02|C2Cantar uma canção\n|11Eu não sei|BF", NULL);
EZTR_Basic_ReplaceText(0x290E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, sério?|11Mas você ouviu com atenção, então a mamãe|11está feliz.|19", NULL);
EZTR_Basic_ReplaceText(0x290F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Vou te dar um doce como seu|11prêmio.|19", NULL);
EZTR_Basic_ReplaceText(0x2910, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Isso mesmo, mas você não podia simplesmente|11cantar aquela música em qualquer lugar.|11|12100 passos para o norte,|11100 passos para o sul,|11100 passos para o leste,|11100 passos para o oeste.|10O local onde esses gigantes|11se separaram é bem no meio|11desta cidade.|BF", NULL);
EZTR_Basic_ReplaceText(0x2911, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, você está acordado?|11|12Acho que aquela história foi um pouco|11difícil para o Tortus.|11|12Mas não desista. Tente de novo mais tarde.|BF", NULL);
EZTR_Basic_ReplaceText(0x2912, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, Tortus, você está pronto?|11|12Faz tempo que não fazemos um piquenique no|11Rancho Romani, não faz?|BF", NULL);
EZTR_Basic_ReplaceText(0x2913, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O vestido de noiva dela não é lindo?|11|12Nós prometemos um ao outro quando éramos|11crianças que nos casaríamos no|11dia do Carnaval do Tempo.|11|12...Mas minha promessa...|11Eu não consegui cumprir.|BF", NULL);
EZTR_Basic_ReplaceText(0x2914, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu...Eu já te encontrei antes.|11|12Que cheiro familiar. Há muito, muito|11tempo...Sim. Ainda éramos jovens.|11Fizemos uma promessa...|11Não fizemos?|10As máscaras do sol e da|11lua...|11|12Iríamos trocá-las no|11dia do Carnaval do Tempo...|BF", NULL);
