EZTR_Basic_ReplaceText(0x2916, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Bem-vindo de volta.|BF", NULL);
EZTR_Basic_ReplaceText(0x2917, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05...Hi-hi! Eles são amantes, mas parecem|11exatamente como uma mãe e filho.|BF", NULL);
EZTR_Basic_ReplaceText(0x2918, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Vamos trocar as máscaras|11prometidas.|BF", NULL);
EZTR_Basic_ReplaceText(0x2919, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Trocamos nossos juramentos e|11nos tornamos um |01casal|00.|BF", NULL);
EZTR_Basic_ReplaceText(0x291A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Vocês são nossas testemunhas.|11Por favor, aceitem esta |01máscara|00.|BF", NULL);
EZTR_Basic_ReplaceText(0x291B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por favor, procurem abrigo.|11Estamos bem aqui.|11|12Saudaremos a manhã...|11juntos.|19", NULL);
EZTR_Basic_ReplaceText(0x291C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Hmmm...Ah, bem, isso não vai funcionar...|11Não...Isso é muito básico... |19", NULL);
EZTR_Basic_ReplaceText(0x291D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Temos que estar prontos sem nenhum|11ensaio desta vez...Todas as vezes...|19", NULL);
EZTR_Basic_ReplaceText(0x291E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Precisamos de um novo passo...Talvez com|11mais pulos...|19", NULL);
EZTR_Basic_ReplaceText(0x291F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Marilla gosta desta coreografia,|11mas ela não se empolga nem um pouco...|19", NULL);
EZTR_Basic_ReplaceText(0x2920, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Judo é muito bom nisso...|11Talvez devêssemos adicionar alguns|11giros...|19", NULL);
EZTR_Basic_ReplaceText(0x2921, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se fizermos um trabalho ruim ao estendê-lo,|11a plateia vai ficar entediada...|19", NULL);
EZTR_Basic_ReplaceText(0x2922, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Talvez eu culpe o líder da trupe|11e volte para a vila...|11Mas Judo não gostaria.|19", NULL);
EZTR_Basic_ReplaceText(0x2923, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Não devemos mudar a música|11agora...Guru-Guru é assustador quando ele|11fica bravo...|19", NULL);
EZTR_Basic_ReplaceText(0x2924, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Estamos bem preparados, mas nosso|11líder da trupe parece estar agindo|11estranho por algum motivo.|11Bem, ainda nem vimos o|10palco... Parece que vamos|11direto para o grande show sem|11nenhum ensaio.|19", NULL);
EZTR_Basic_ReplaceText(0x2925, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mestre!|11Por favor, venha à nossa apresentação!|19", NULL);
EZTR_Basic_ReplaceText(0x2926, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Não nos incomode!!!|19", NULL);
EZTR_Basic_ReplaceText(0x2927, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Obrigado por nos ensinar esses|11passos.|BF", NULL);
EZTR_Basic_ReplaceText(0x2928, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Você é nosso mestre!|BF", NULL);
EZTR_Basic_ReplaceText(0x2929, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mestre! Você é demais!|BF", NULL);
EZTR_Basic_ReplaceText(0x292A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Doo-doo-doooo...|11Não fale com ela agora. |11|12Ela não terminou sua nova dança|11para o carnaval da cidade|11Doo-da-daa...|11|12Mesmo que a música esteja pronta.|19", NULL);
EZTR_Basic_ReplaceText(0x292B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Doot-doo-dooo...|11Não resta tempo.|11A dança ainda não terminou.|11|12A música agora está pronta,|11mas a dança não.|11|12Gostaria que alguém lhes ensinasse|11um...Um passo elegante para essas garotas.|11...Do-dee-do...|19", NULL);
EZTR_Basic_ReplaceText(0x292C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "La-la-la...|11Eles disseram que eu estava|11muito alto|11quando pratiquei no meu quarto.|10Eles ficaram bravos.|11Suspiro...Agora estou triste|11Vou ficar aqui a noite toda e|11longe da casa deles.|19", NULL);
EZTR_Basic_ReplaceText(0x292D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "La-la-la...|11Eles disseram que eu estava|11muito alto|11quando pratiquei no meu quarto.|10Eles ficaram bravos.|11Suspiro...Agora estou triste.|11Vou apenas pensar no passado|11para tirar o ruim da cabeça.|10Ah, sim, vou fazer isso...|19", NULL);
EZTR_Basic_ReplaceText(0x292E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Caro hóspede...Há muito tempo, eu estava em uma|11trupe de animais, com cães e|11burros e tal.|19", NULL);
EZTR_Basic_ReplaceText(0x292F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por que um...? Por que um...?|11Por que um homem poderia entrar?!?|11É porque um homem também é um animal,|11meu rapaz!|19", NULL);
EZTR_Basic_ReplaceText(0x2930, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eles eram todos ótimos. Mas havia|11uma coisa que eu não gostava|11nisso...|19", NULL);
EZTR_Basic_ReplaceText(0x2931, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por que o...? Por que o...?|11Por que o cachorro era o líder?!?|11Será que havia algo|11errado comigo, senhor???|19", NULL);
EZTR_Basic_ReplaceText(0x2932, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, aquele cachorro era um líder|11incrível! Ele sempre teve uma|11trupe estelar, não importa com quais|11animais ele tivesse que trabalhar...|19", NULL);
EZTR_Basic_ReplaceText(0x2933, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "É por isso que eu... É por isso que eu...|11É por isso que eu a roubei...|11A |01máscara|00 do cachorro.|11Eu a roubei.|19", NULL);
EZTR_Basic_ReplaceText(0x2934, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu queria porque era a|11máscara do líder...|19", NULL);
EZTR_Basic_ReplaceText(0x2935, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas eu não preciso mais dela...|11Eu a dou ao meu convidado.|19", NULL);
EZTR_Basic_ReplaceText(0x2936, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O líder era um bom instrutor.|11Seus membros amadureceram rapidamente e|11se tornaram adultos em um instante.|19", NULL);
EZTR_Basic_ReplaceText(0x2937, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Minha, minha! Coisas engraçadas estão|11acontecendo na cidade, não estão?|11Engraçado. Engraçado.|19", NULL);
EZTR_Basic_ReplaceText(0x2938, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nem me diga! Como os rumores|11sobre o |01pântano|00 ao |01sul|00?|11Você ouviu falar sobre o|11sequestro?|19", NULL);
EZTR_Basic_ReplaceText(0x2939, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, meu!|11O sequestro?|19", NULL);
EZTR_Basic_ReplaceText(0x293A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Sim!|11Mas então o garoto acordou.|11Entendeu? Garoto dormindo (kid napping)?|11Hooo...Tenho um milhão delas!|19", NULL);
EZTR_Basic_ReplaceText(0x293B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Hoo, hoo, hoo, hoo, hoo!|BF", NULL);
EZTR_Basic_ReplaceText(0x293C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Somos os malabaristas gêmeos da|11Trupe Gorman! Estamos praticando|11para o grande carnaval! Acontece|11uma vez na vida!|19", NULL);
EZTR_Basic_ReplaceText(0x293D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "ou, no caso deste ano, uma vez em|11uma lua muito, muito assustadora e de olhos|11vermelhos!|19", NULL);
EZTR_Basic_ReplaceText(0x293E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ho! Ho! Ouvi dizer que vai cair|11mais forte do que a forma como meu irmão|11desajeitado está sempre derrubando nossas|11bolas de malabarismo!|19", NULL);
EZTR_Basic_ReplaceText(0x293F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Veja bem, somos artistas. Devemos|11manter as pessoas sorrindo. Não|11importa quão sombrias as coisas fiquem,|11devemos sempre ser otimistas!|19", NULL);
