EZTR_Basic_ReplaceText(0x2941, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Elas são gêmeas como nós! Você|11pode acreditar? Acho que elas estão|11praticando em algum lugar na Cidade|11Relógio Oeste agora.|19", NULL);
EZTR_Basic_ReplaceText(0x2942, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Há dois pares de gêmeos|11viajando na trupe de artistas de Gorman!|11Quer dizer, quais são as|11chances?|19", NULL);
EZTR_Basic_ReplaceText(0x2943, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu diria que as chances são de uma|11em um milhão! Não, espere...|11Faça quatro em um milhão!|19", NULL);
EZTR_Basic_ReplaceText(0x2944, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Gostaria de se juntar ao nosso|11pequeno jogo de cartas?|19", NULL);
EZTR_Basic_ReplaceText(0x2945, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Você está brincando, não está, irmão?|11Ele vai deixar nosso jogo muito complexo!|19", NULL);
EZTR_Basic_ReplaceText(0x2946, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que você quer dizer?|19", NULL);
EZTR_Basic_ReplaceText(0x2947, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "É fácil jogar contra você!|11Você se parece comigo, então eu já|11sei como você fica quando|11está blefando!|19", NULL);
EZTR_Basic_ReplaceText(0x2948, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Pa-Pa-Pa-Papel, por favor!|19", NULL);
EZTR_Basic_ReplaceText(0x2949, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "N-Não é isso!|19", NULL);
EZTR_Basic_ReplaceText(0x294A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Sim!|19", NULL);
EZTR_Basic_ReplaceText(0x294B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ho!|11Você me salvou...|19", NULL);
EZTR_Basic_ReplaceText(0x294C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Isso caiu aqui...|11Vou te dar.|19", NULL);
EZTR_Basic_ReplaceText(0x294D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "La-la-la...Eles disseram que eu estava muito alto|11quando pratiquei no meu quarto.|11|12Eles ficaram bravos.|11Suspiro...Agora estou triste.|11Vou ficar aqui a noite toda e|11longe da casa deles.|10E você é uma criança, então você deve|11ir para a cama.|19", NULL);
EZTR_Basic_ReplaceText(0x294E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "La-la-la...Eles disseram que eu estava muito alto|11quando pratiquei no meu quarto.|11|12Eles ficaram bravos.|11Até de manhã, ficarei aqui.|11Até a dor passar, ficarei aqui.|11Do-da-da, do-dee, do-dee...|19", NULL);
EZTR_Basic_ReplaceText(0x294F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, que hóspede fofo.|11Você tem reserva?|11Onde está sua mãe?|19", NULL);
