EZTR_Basic_ReplaceText(0x2952, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Olá, Sr. Scrub.|11Que tal esta chuva?|11|12Vocês scrubs se sentem tristes em dias|11chuvosos também?|11|12....|11Mas os Deku Scrubs deveriam|11gostar de chuva. Pelo menos um de nós tem|11razão para estar feliz...|BF", NULL);
EZTR_Basic_ReplaceText(0x2953, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu preciso ser mais feliz, não preciso?|BF", NULL);
EZTR_Basic_ReplaceText(0x2954, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Não fale comigo usando uma|11máscara tão desagradável!|BF", NULL);
EZTR_Basic_ReplaceText(0x2955, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por favor, procurem abrigo.|11Estamos bem aqui.|11|12Saudaremos a manhã...|11juntos.|BF", NULL);
EZTR_Basic_ReplaceText(0x2956, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Você realmente não tem, goro?|19", NULL);
EZTR_Basic_ReplaceText(0x2957, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu realmente não tenho.|19", NULL);
EZTR_Basic_ReplaceText(0x2958, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Sério, goro?|19", NULL);
EZTR_Basic_ReplaceText(0x2959, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Sinto muitíssimo.|19", NULL);
EZTR_Basic_ReplaceText(0x295A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Uhm, Anj..|11Nós vamos sair imediatamente...|11Resmunga, resmunga....|BF", NULL);
EZTR_Basic_ReplaceText(0x295B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O vento ficou úmido, goro...|11Amanhã chove, goro... |11Goro-goro...|BF", NULL);
EZTR_Basic_ReplaceText(0x295C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por favor, me diga!|19", NULL);
