EZTR_Basic_ReplaceText(0x2AA5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, sério?|11Então, deve ficar tudo bem se você|11simplesmente entrar.|19", NULL);
EZTR_Basic_ReplaceText(0x2AA6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Madame Aroma, eu sou Gorman.|11Já faz algum tempo...|11|12Obrigado por nos deixar nos apresentar|11no Carnaval do Tempo deste ano.|19", NULL);
EZTR_Basic_ReplaceText(0x2AA7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, meu Deus...|11Gorman! Há um problema!|19", NULL);
