EZTR_Basic_ReplaceText(0x2AAD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Permitam-me explicar.|11|12Oh, com licença... Eu devo|11trabalhar no show deste ano|11...ou esse era o plano.|19", NULL);
EZTR_Basic_ReplaceText(0x2AAE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu sou Toto, gerente da banda Zora,|11The Indigo-Go's.|19", NULL);
EZTR_Basic_ReplaceText(0x2AAF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ele chegou esta manhã.|19", NULL);
EZTR_Basic_ReplaceText(0x2AB0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Na verdade, houve um|11acidente incomum na Grande Baía...|11|12E devido a este acidente incomum,|11Lulu, a diva do The Indigo-Go's,|11perdeu a voz.|19", NULL);
EZTR_Basic_ReplaceText(0x2AB1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por quê?|19", NULL);
EZTR_Basic_ReplaceText(0x2AB2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por quê?|19", NULL);
EZTR_Basic_ReplaceText(0x2AB3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Os detalhes são bem longos, então vou|11poupá-los. De qualquer forma...|11|12Devo cancelar nossa apresentação no|11Carnaval do Tempo deste ano.|19", NULL);
EZTR_Basic_ReplaceText(0x2AB4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Veja!|19", NULL);
EZTR_Basic_ReplaceText(0x2AB5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Então isso significa...|11o trabalho da...|11Troupe Gorman é...|19", NULL);
EZTR_Basic_ReplaceText(0x2AB6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Está cancelado...|19", NULL);
EZTR_Basic_ReplaceText(0x2AB7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ma-mas isso!|19", NULL);
EZTR_Basic_ReplaceText(0x2AB8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "É tudo, Gorman. Sempre há|11o próximo ano. Estou ocupado com|11outros assuntos.|19", NULL);
EZTR_Basic_ReplaceText(0x2AB9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Bah! Que chato! Que chato!|11Estou ocupado!|BF", NULL);
EZTR_Basic_ReplaceText(0x2ABA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Estou com raiva agora!|11Não fale comigo.|11|12...Eles devem estar brincando. E agora|11o que eu vou fazer?!?|BF", NULL);
EZTR_Basic_ReplaceText(0x2ABB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Todos devem se refugiar!!!|19", NULL);
EZTR_Basic_ReplaceText(0x2ABC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Avante com o carnaval!!!|19", NULL);
EZTR_Basic_ReplaceText(0x2ABD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A maioria dos moradores da cidade já|11se abrigou sem esperar|11pelas ordens do Prefeito.|11|12Os únicos que restam são servidores|11públicos e membros do comitê...|11|12Sr. Prefeito e Membros do Comitê do|11Carnaval, por favor, ordenem que os que|11restam evacuem!|19", NULL);
EZTR_Basic_ReplaceText(0x2ABE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ahh...hmm...bem...|19", NULL);
EZTR_Basic_ReplaceText(0x2ABF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Seus covardes! Vocês realmente|11acreditam que a lua vai cair?|11|12Os moradores confusos simplesmente|11causaram pânico ao acreditar nesta|11teoria ridícula e sem fundamento.|11|12Os soldados não conseguiram evitar o|11pânico, mas fora dos muros da cidade |11é onde o perigo está!|11|12Querem respostas? A resposta é|11que o carnaval não deve ser|11cancelado!|19", NULL);
EZTR_Basic_ReplaceText(0x2AC0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Não é mesmo, Sr. Prefeito?|19", NULL);
EZTR_Basic_ReplaceText(0x2AC1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Você está falando sério, Mutoh?!?|11|12Parece que aquele pedaço gigante de rocha|11acima de nós não chamou sua atenção!|11|12Nesta época do ano, somos|11invadidos por turistas! Então, por que|11a cidade está vazia?|11|12Claramente, é seu trabalho garantir|11a operação do carnaval, mas isso é|11se houver pessoas para ele!|11|12Não arraste os comerciantes e|11os soldados para isso!|19", NULL);
EZTR_Basic_ReplaceText(0x2AC2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mmm...Hmm...|19", NULL);
EZTR_Basic_ReplaceText(0x2AC3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se os soldados desejam fugir, então|11fujam, Viscen! Nós, conselheiros, vamos|11manter a tradição.|11|12Este carnaval será um sucesso!|11Nunca ouvi falar de uma unidade de defesa|11abandonando sua cidade!|11|12Madame Aroma certamente diria|11a mesma coisa, não diria,|11Prefeito Dotour?|19", NULL);
EZTR_Basic_ReplaceText(0x2AC4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Não vamos envolver minha esposa nisso.|19", NULL);
EZTR_Basic_ReplaceText(0x2AC5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Você também se refugia.|19", NULL);
EZTR_Basic_ReplaceText(0x2AC6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah!|19", NULL);
EZTR_Basic_ReplaceText(0x2AC7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah!|19", NULL);
EZTR_Basic_ReplaceText(0x2AC8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah!|19", NULL);
EZTR_Basic_ReplaceText(0x2AC9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A |01Máscara do Casal|00. Que boa|11lembrança... Então, um jovem casal se|11casou.|19", NULL);
EZTR_Basic_ReplaceText(0x2ACA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu me pergunto... Minha esposa fugiu?|19", NULL);
EZTR_Basic_ReplaceText(0x2ACB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|17O quê?!?|18|11O que você acabou de dizer?!?|19", NULL);
EZTR_Basic_ReplaceText(0x2ACC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Sim, sim, todos. Estamos todos|11preocupados com nossas famílias. Por que não|11encerramos esta reunião?|19", NULL);
EZTR_Basic_ReplaceText(0x2ACD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas, Sr. Prefeito!|19", NULL);
EZTR_Basic_ReplaceText(0x2ACE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Isso basta. Se você é|11teimoso e vai ficar para guardar|11sua família, ou se prefere|11fugir para longe e procurar abrigo...|10Isso é algo para as pessoas decidirem|11por conta própria.|19", NULL);
EZTR_Basic_ReplaceText(0x2ACF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "........!|19", NULL);
EZTR_Basic_ReplaceText(0x2AD0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Obrigado por me permitir colocar|11um fim a toda essa discussão|11inútil.|11|12Adultos são tão teimosos...|11É vergonhoso.|11|12Aqui está um sinal da minha gratidão.|19", NULL);
EZTR_Basic_ReplaceText(0x2AD1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Bem, eu posso ser um prefeito|11não confiável, mas pelo menos minha família pode|11depender de mim. Eu quero proteger|11minha esposa.|19", NULL);
EZTR_Basic_ReplaceText(0x2AD2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Eu te digo... É difícil descobrir|11para que lado as coisas vão.|19", NULL);
EZTR_Basic_ReplaceText(0x2AD3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Eu te digo... É difícil descobrir|11para que lado as coisas vão.|11|12Veja, porque Mutoh disse que iria|11ligar para minha esposa...|19", NULL);
EZTR_Basic_ReplaceText(0x2AD4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O carnaval está... mantido.|19", NULL);

EZTR_Basic_ReplaceText(0x2AD5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Capitão Viscen!|19", NULL);
EZTR_Basic_ReplaceText(0x2AD6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...As ordens do prefeito são absolutas!|19", NULL);
EZTR_Basic_ReplaceText(0x2AD7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Então os guardas do portão ainda|11estão de prontidão...|19", NULL);
EZTR_Basic_ReplaceText(0x2AD8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...De prontidão!|11Mas que droga!|19", NULL);
EZTR_Basic_ReplaceText(0x2AD9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Bem-vindo|11Tem algum|11assunto a tratar?|19", NULL);
EZTR_Basic_ReplaceText(0x2ADA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A sala à esquerda é o|11escritório do prefeito...|11|12Parece que estão tendo uma reunião|11lá dentro, eu acho.|19", NULL);
EZTR_Basic_ReplaceText(0x2ADB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A sala à direita é a sala de estar|11e também o escritório da Madame|11Aroma. |BF", NULL);
EZTR_Basic_ReplaceText(0x2ADC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Minhas instruções...|11Quer ouvi-las de novo?|19", NULL);
EZTR_Basic_ReplaceText(0x2ADD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Então...|19", NULL);
EZTR_Basic_ReplaceText(0x2ADE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A sala à esquerda é o Escritório do|11Prefeito...|11|12E a sala à direita é a sala de estar|11e também o escritório da Madame|11Aroma.|BF", NULL);
EZTR_Basic_ReplaceText(0x2ADF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A sala à esquerda é o Escritório do|11Prefeito...|11|12Parece que aquela... sei lá... reunião|11acabou. Um monte de brutamontes saiu|11de lá.|19", NULL);
EZTR_Basic_ReplaceText(0x2AE0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A sala à direita é a sala de estar e|11também o escritório da Madame Aroma.|11|12Não entre sem marcar horário. Ela|11vai ficar brava com você.|BF", NULL);
EZTR_Basic_ReplaceText(0x2AE1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "As nadadeiras andam úmidas ultimamente?|19", NULL);
EZTR_Basic_ReplaceText(0x2AE2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah. Esse é o cumprimento usado|11entre nós, os Zora.|19", NULL);
EZTR_Basic_ReplaceText(0x2AE3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Cadê sua mamãe, garotinho? Hein?|11Veio aqui sozinho? Você é um|11menino corajoso!|BF", NULL);
EZTR_Basic_ReplaceText(0x2AE4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Quando for mais velho, venha ver|11os Indigo-Go’s ao vivo no|11Salão Zora.|BF", NULL);
EZTR_Basic_ReplaceText(0x2AE5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh céus, você é aluno da|11Escola Deku?|11Onde está seu professor?|11|12Você não devia estar aqui. Excursões|11são ao lado. Avise seu professor.|BF", NULL);
EZTR_Basic_ReplaceText(0x2AE6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Achou seu professor?|11Seu professor não está aqui???|11Bom, então não sei o que fazer|11com você...|BF", NULL);
EZTR_Basic_ReplaceText(0x2AEA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que eu devo fazer?|11Digo, a Trupe Gorman, o que deve fazer?|19", NULL);
EZTR_Basic_ReplaceText(0x2AEB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, Gorman, queria que fosse só seu|11rosto me incomodando agora.|BF", NULL);
EZTR_Basic_ReplaceText(0x2AEC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Então posso entrar, senhorita?|19", NULL);
EZTR_Basic_ReplaceText(0x2AED, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ahh... Acho que sim.|19", NULL);
EZTR_Basic_ReplaceText(0x2AEE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "....|BF", NULL);

EZTR_Basic_ReplaceText(0x2AF8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "É isso, então...|BF", NULL);
EZTR_Basic_ReplaceText(0x2AF9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O bar abre à noite, senhor.|11|12E é exclusivo para membros. Não|11aceitamos pessoas sem |01prova de|11membro|00.|11|12Bem, estou preparando as coisas|11agora, então, se não atrapalhar|11a limpeza, pode ficar.|BF", NULL);
EZTR_Basic_ReplaceText(0x2AFA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Somos chamados de |01Bar do Leite|00, e|11servimos o |03leite da noite|00.|11|12O mais popular, claro, é o|11|01Chateau Romani|00. Um leite refinado.|11|12Vem do Rancho Romani e custa|11|06200 rupias|00!|11|12...Não ficou surpreso?|19", NULL);
EZTR_Basic_ReplaceText(0x2AFB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Há algo ainda mais surpreendente|11sobre esse leite...|11|12Dependendo de quem você perguntar,|11alguns dizem que ele é uma fonte de|11|02Poder Mágico|00!|11Basta um gole, dizem!|10É caro, mas felizmente é o mais|11servido por aqui.|19", NULL);
EZTR_Basic_ReplaceText(0x2AFC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ontem à noite, recebemos leite|11fresco pela primeira vez em muito|11tempo.|11|12Finalmente podemos confiar na|11qualidade das bebidas.|11|12Mas aquela lua... Nossos clientes|11habituais fugiram. Então, não há|11mesmo boas notícias.|BF", NULL);
EZTR_Basic_ReplaceText(0x2AFD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Pra piorar, estamos com|11estoque baixo.|19", NULL);
EZTR_Basic_ReplaceText(0x2AFE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Há uma estrada ao |01sul|00 da cidade|11chamada |01Estrada do Leite|00.|11Pode ser uma pegadinha de alguém...|10A estrada está bloqueada por uma|11grande |01pedra|00.|11Agora não consigo leite do rancho,|10e não posso satisfazer meus|11clientes. Isso é terrível!|BF", NULL);
EZTR_Basic_ReplaceText(0x2AFF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Também está procurando pelo|11jovem Kafei?|11|12Parece que Madame Aroma ainda|11não sabe onde ele está...|11Mas ele não é do tipo que fugiria!|10Deve ter um motivo para não|11aparecer.|11|12Aguarde... Quando for o momento|11certo, ele vai se mostrar.|BF", NULL);
EZTR_Basic_ReplaceText(0x2B00, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A máscara do jovem, hein?|11Acho que é perda de tempo|11procurá-lo.|BF", NULL);
EZTR_Basic_ReplaceText(0x2B01, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Tá olhando o quê?!?|19", NULL);
EZTR_Basic_ReplaceText(0x2B02, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Parece que seu show foi cancelado.|11Você não precisa mais estar aqui.|19", NULL);
EZTR_Basic_ReplaceText(0x2B03, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Vim beber!|11E... eu sou um cliente!!!|19", NULL);
EZTR_Basic_ReplaceText(0x2B04, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Bom, cliente, o bar abre às|11|0110 horas da noite|00.|11Espere até lá. E além disso...|19", NULL);
EZTR_Basic_ReplaceText(0x2B05, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Este bar é só para membros.|11Quem não tiver prova de membro|11não pode entrar.|19", NULL);
EZTR_Basic_ReplaceText(0x2B06, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Então não quero leite!|11Só quero sentar e pensar um pouco...|11|12Só me dê um lugar para isso...|19", NULL);
EZTR_Basic_ReplaceText(0x2B07, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Tudo bem. Fique à... vontade.|19", NULL);
EZTR_Basic_ReplaceText(0x2B08, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ohhhh... O que vou dizer|11para os membros da trupe?|BF", NULL);
EZTR_Basic_ReplaceText(0x2B09, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Senhor... São as regras. Por favor,|11use a |01Máscara da Romani|00 dentro do bar.|BF", NULL);
EZTR_Basic_ReplaceText(0x2B0A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Bem-vindo...|11 |11|02|02|C2Falar com o balconista\n|11Tomar uma bebida|BF", NULL);
EZTR_Basic_ReplaceText(0x2B0B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que vai ser?|11|12|02Leite comum: |0620 rupias|11|02Chateau: |06200 rupias|11|02Nada|BF", NULL);
EZTR_Basic_ReplaceText(0x2B0C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Você não tem |06rupias|00 suficientes, senhor.|BF", NULL);

EZTR_Basic_ReplaceText(0x2B0D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Me chame quando decidir.|BF", NULL);
EZTR_Basic_ReplaceText(0x2B0E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Os membros deste clube trazem|11seus próprios copos.|11|12Pedimos que tenha uma garrafa|11vazia para beber quando fizer|11um pedido.|BF", NULL);
EZTR_Basic_ReplaceText(0x2B0F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Existe uma estrada ao |01sul|00 da|11cidade chamada |01Estrada do Leite|00.|11|12Alguém deve ter feito uma pegadinha|11lá, pois ela está bloqueada por|11uma grande |01pedra|00.|11|12Não consigo trazer leite do rancho,|11então não sei se devo recomendar|11o Chateau Romani para você.|BF", NULL);
EZTR_Basic_ReplaceText(0x2B10, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Como pode ver, todos os clientes|11foram embora.|11|12Talvez eu esteja me condenando,|11mas sou do tipo que mantém|11o negócio aberto em qualquer|11situação.|11|12E sigo aqui, no balcão, esperando|11um de meus clientes favoritos...|11|12E eu estava certo.|11Veja, você veio.|BF", NULL);
EZTR_Basic_ReplaceText(0x2B11, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Temos um bom leite esta noite.|11|12Gostaria de um Romani para|11sua última noite sob a lua?|BF", NULL);
EZTR_Basic_ReplaceText(0x2B12, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Lembro-me de quando estava no|11rancho. Meus irmãos...|11Como será que estão?|BF", NULL);
EZTR_Basic_ReplaceText(0x2B13, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ei... Você aí!|11|12Leite...|11|12É leeeite...|11|12Será que dá pra ficar tonto com|11algo como leite?!? Hic!|BF", NULL);
EZTR_Basic_ReplaceText(0x2B14, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...O quê? Hic!|11|12...Não olha pra mim! Hic!|19", NULL);
EZTR_Basic_ReplaceText(0x2B15, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "De qualquer forma, sou só o|11odiado segundo filho!|11|12Não consigo lidar com cavalos|11como meu irmão mais velho!|11|12Nem cuidar deles como o|11meu irmão mais novo!|19", NULL);
EZTR_Basic_ReplaceText(0x2B16, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Saí do rancho, conheci o mundo|11do entretenimento...|11Viajei por aí...|11Mas pra quê?|19", NULL);
EZTR_Basic_ReplaceText(0x2B17, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Pra nada!!!|19", NULL);
EZTR_Basic_ReplaceText(0x2B18, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, eu tinha que entrar no mundo|11do espetáculo, né?|11Tá frio... Tão frio...|19", NULL);
