EZTR_Basic_ReplaceText(0x349F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Temos que dar algo pra ele.|11Alem disso, nem precisamos mais disso,|11entao qual o problema?|19", NULL);
EZTR_Basic_ReplaceText(0x34A0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Em troca, nao queremos que|11voce conte a ninguem de onde|11conseguiu isso!|19", NULL);
EZTR_Basic_ReplaceText(0x34A1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Temos que dar algo pra ele. E|11esse algo e... leite!|19", NULL);
EZTR_Basic_ReplaceText(0x34A2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ugh... Eu sabia... Voce nao tem|11nenhuma garrafa vazia com voce!|19", NULL);
EZTR_Basic_ReplaceText(0x34A3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, que pena. E eu ia mesmo|11te dar um pouco de leite se voce|11tivesse uma garrafa vazia pra guardar...|11E verdade! Que penaaaa!|19", NULL);
