EZTR_Basic_ReplaceText(0x34A9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, essa mascara...|19", NULL);
EZTR_Basic_ReplaceText(0x34AA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Esse e o irmao mais velho do nosso|11irmao do meio!|19", NULL);
EZTR_Basic_ReplaceText(0x34AB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Entao, ele entrou no mundo do|11entretenimento...|11|12Aquele meu irmao mais novo esta|11realmente se esforcando...|19", NULL);
