EZTR_Basic_ReplaceText(0x3520, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que voce quer?|11|12Este e o Canodromo da Mamamu Yan,|11igual diz na placa.|19", NULL);
EZTR_Basic_ReplaceText(0x3521, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Quer tentar uma corrida de caes?|11A |01aposta|00 minima e de |0610 rupias|00.|11|12Ainda quer tentar?|11 |11|02|02|C2Sim\n|11Nao|BF", NULL);
EZTR_Basic_ReplaceText(0x3522, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Entao primeiro, entre e pegue o|11|01caozinho|00 que voce acha que vai correr|11|01mais rapido|00 e traga ele aqui!|19", NULL);
