EZTR_Basic_ReplaceText(0x352A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Entao me leve pra passear e me chame|11de Rex! Voce ficou em |011o lugar|00.|11|011o lugar|00!!!|11|12Voce ganhou |01triplo|00 do valor da|11sua aposta! Isso e !|19", NULL);
EZTR_Basic_ReplaceText(0x352B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Doces caes da felicidade!|11Voce ficou em |012o|00 lugar! Incrivel!|11|12Voce ganhou |01dobro|00 do valor da|11sua aposta! !|19", NULL);
EZTR_Basic_ReplaceText(0x352C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, quase...|11Bem, vou te devolver o valor|11que voce apostou.|19", NULL);
