EZTR_Basic_ReplaceText(0x3533, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que voce quer num dia|11como este?|11|12Este e o Canodromo da Mamamu Yan. Voce nao sabia?|19", NULL);
EZTR_Basic_ReplaceText(0x3534, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que voce quer?|11Voce vai ficar bem aqui?|11|12Este e o Canodromo da Mamamu Yan! Voce tem isso?|19", NULL);
