EZTR_Basic_ReplaceText(0x353D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ruff!|11|17Sera que meu dono de carinha fofa|11vai me deixar parar de treinar...?|18", NULL);
EZTR_Basic_ReplaceText(0x353E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Rrr-Ruff!|11|17Acho que vou me sair bem!|18", NULL);
EZTR_Basic_ReplaceText(0x353F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Rrr-Ruff!|11|17Sinto que posso vencer, mas tambem|11sinto que posso perder...|18", NULL);
